typedef unsigned int size_t;

extern "C" void arch_free(void *) __asm__("arch_free__FPv");
extern "C" void object_delete(void *) __asm__("__builtin_delete");
extern void *__default_alloc_free_list[16];
extern const char singleton_vtable[];

__asm__(".equ arch_free__FPv, 0x002AC768");
__asm__(".equ __builtin_delete, 0x002AC6B0");
__asm__(".equ __default_alloc_free_list, 0x003E5628");
__asm__(".equ singleton_vtable, 0x004BE7A8");

template<class T>
struct my_allocator {
    static void deallocate(T *pointer, size_t count)
    {
        size_t bytes = count * sizeof(T);
        if (bytes > 128) {
            arch_free(pointer);
        } else {
            void **free_list =
                __default_alloc_free_list + (((bytes + 7) >> 3) - 1);
            *(void **)pointer = *free_list;
            *free_list = pointer;
        }
    }
};

template<class T, class Allocator>
struct simple_alloc {
    static void deallocate(T *pointer, size_t count)
    {
        if (count != 0)
            Allocator::deallocate(pointer, count);
    }
};

struct signal;

struct signal_vector {
    signal **start;
    signal **finish;
    signal **end_of_storage;

    ~signal_vector()
    {
        simple_alloc<signal *, my_allocator<signal *> >::deallocate(
            start, end_of_storage - start
        );
    }
};

struct stringx {
    char *chars;
    void *buffer;
};

struct map_value {
    stringx first;
    unsigned short second;
    unsigned short padding;
};

struct rb_node {
    int color;
    rb_node *parent;
    rb_node *left;
    rb_node *right;
    map_value value;
};

