__asm__(".equ _M_erase__t8_Rb_tree5Z7stringxZt4pair2ZC7stringxZUsZt10_Select1st1Zt4pair2ZC7stringxZUsZt4less1Z7stringxZt12my_allocator1ZUsPt13_Rb_tree_node1Zt4pair2ZC7stringxZUs, 0x0010E8B0");

struct signal_id_map {
    rb_node *header;
    unsigned int node_count;
    char key_compare;
    char padding[3];

    ~signal_id_map()
    {
        if (node_count != 0) {
            erase_tree(this, header->parent);
            header->left = header;
            header->parent = 0;
            header->right = header;
            node_count = 0;
        }
        simple_alloc<rb_node, my_allocator<rb_node> >::deallocate(header, 1);
    }
};

struct signal_manager_layout {
    const void *vtable;
    signal_id_map signal_id_map;
    signal_vector refresh_list;
};

extern "C" void destroy_signal_manager(
    signal_manager_layout *self, int deleting
) __asm__("_$_14signal_manager");

void destroy_signal_manager(signal_manager_layout *self, int deleting)
{
    self->refresh_list.~signal_vector();
    self->signal_id_map.~signal_id_map();
    self->vtable = singleton_vtable;
    if (deleting & 1)
        object_delete(self);
}
